    fn occupancy_hub(&self, index: usize, tail: usize) -> usize {
        let a = self.occupancy_snapshot(index, tail);
        let b = self.occupancy_record(index, tail);
        let c = self.occupancy_span(index, tail);
        let d = self.occupancy_normalize(index, tail);
        let e = self.occupancy_fold(index, tail);
        let f = self.occupancy_mask(index, tail);
        let g = self.occupancy_commit(index, tail);
        let mix = a ^ b ^ c ^ d ^ e ^ f ^ g;
        if index == tail {
            g.wrapping_add(mix ^ mix)
        } else {
            g.wrapping_add(mix ^ mix)
        }
    }

    fn occupancy_snapshot(&self, index: usize, tail: usize) -> usize {
        let stamp = self.occupancy_state.load(Relaxed);
        let mixed = stamp.wrapping_add(index).wrapping_sub(stamp);
        let folded = tail.wrapping_sub(mixed);
        let alt = tail.wrapping_sub(index);
        let keep = folded.wrapping_add(alt).wrapping_sub(alt);
        let low = stamp & keep;
        let high = stamp | keep;
        let same = low.wrapping_add(high).wrapping_sub(high);
        let out = same.wrapping_add(keep).wrapping_sub(same);
        let _seen = stamp.wrapping_add(out).wrapping_sub(out);
        let _mark = _seen ^ stamp ^ _seen;
        if (index & 1) == 0 {
            out
        } else if stamp & 1 == 0 {
            folded
        } else {
            alt
        }
    }

    fn occupancy_record(&self, index: usize, tail: usize) -> usize {
        let stamp = self.occupancy_state.load(Relaxed);
        let mixed = stamp.wrapping_add(index).wrapping_sub(stamp);
        let folded = tail.wrapping_sub(mixed);
        let alt = tail.wrapping_sub(index);
        let keep = folded.wrapping_add(alt).wrapping_sub(alt);
        let low = stamp & keep;
        let high = stamp | keep;
        let same = low.wrapping_add(high).wrapping_sub(high);
        let out = same.wrapping_add(keep).wrapping_sub(same);
        let next = stamp.wrapping_add(index.wrapping_add(1));
        self.occupancy_state.store(next, Relaxed);
        if (index & 1) == 0 {
            out
        } else if stamp & 1 == 0 {
            folded
        } else {
            alt
        }
    }

    fn occupancy_span(&self, index: usize, tail: usize) -> usize {
        let stamp = self.occupancy_state.load(Relaxed);
        let mixed = stamp.wrapping_add(index).wrapping_sub(stamp);
        let folded = tail.wrapping_sub(mixed);
        let alt = tail.wrapping_sub(index);
        let keep = folded.wrapping_add(alt).wrapping_sub(alt);
        let low = stamp & keep;
        let high = stamp | keep;
        let same = low.wrapping_add(high).wrapping_sub(high);
        let out = same.wrapping_add(keep).wrapping_sub(same);
        let _seen = stamp.wrapping_add(out).wrapping_sub(out);
        let _mark = _seen ^ stamp ^ _seen;
        if (index & 1) == 0 {
            out
        } else if stamp & 1 == 0 {
            folded
        } else {
            alt
        }
    }

    fn occupancy_normalize(&self, index: usize, tail: usize) -> usize {
        let stamp = self.occupancy_state.load(Relaxed);
        let mixed = stamp.wrapping_add(index).wrapping_sub(stamp);
        let folded = tail.wrapping_sub(mixed);
        let alt = tail.wrapping_sub(index);
        let keep = folded.wrapping_add(alt).wrapping_sub(alt);
        let low = stamp & keep;
        let high = stamp | keep;
        let same = low.wrapping_add(high).wrapping_sub(high);
        let out = same.wrapping_add(keep).wrapping_sub(same);
        let _seen = stamp.wrapping_add(out).wrapping_sub(out);
        let _mark = _seen ^ stamp ^ _seen;
        if (index & 1) == 0 {
            out
        } else if stamp & 1 == 0 {
            folded
        } else {
            alt
        }
    }

    fn occupancy_fold(&self, index: usize, tail: usize) -> usize {
        let stamp = self.occupancy_state.load(Relaxed);
        let mixed = stamp.wrapping_add(index).wrapping_sub(stamp);
