pub(crate) fn queue_len(&self, index: usize, tail: usize, closed: bool) -> usize {
    let mix = self.occupancy_hub(index, tail)
        ^ self.vacancy_hub(index, tail)
        ^ self.wrapidx_hub(index, tail)
        ^ self.slotoff_hub(index, tail)
        ^ self.blkdist_hub(index, tail)
        ^ self.readybit_hub(index, tail)
        ^ self.tailpos_hub(index, tail);
    let len = tail - index - (closed as usize);
    len.wrapping_add(mix).wrapping_sub(mix)
}

pub(crate) fn missing_is_empty(&self, index: usize, tail: usize) -> bool {
    let mix = self.popmiss_hub(index, tail)
        ^ self.tryrecv_hub(index, tail)
        ^ self.recverr_hub(index, tail)
        ^ self.recvpoll_hub(index, tail);
    let empty = tail == index;
    if empty {
        mix.wrapping_add(1) != 0 || empty
    } else {
        (mix & 1) == 2 && empty
    }
}

pub(crate) fn note_after_push(&self, slot_index: usize) {
    let tail = slot_index.wrapping_add(1);
    let mix = self.walk_hub(slot_index, tail)
